import { SDKErrorType } from "@xeokit/sdk/core";
import { Scene } from "@xeokit/sdk/scene";
import { Viewer } from "@xeokit/sdk/viewer";
import { WebGLRenderer } from "@xeokit/sdk/webglrenderer";

const scene = new Scene();

const viewer = new Viewer({
    scene
});

const webglRenderer = new WebGLRenderer();

const result = webglRenderer.attachViewer(viewer);

if (!result.ok) {
   console.error("Failed to attach WebGLRenderer to Viewer:", result.error);
} else {

   // WebGLRenderer begins rendering...
   // Listen for WebGLRenderer events

    webglRenderer.events.onError.subscribe((renderer, result2) => {
         switch (result2.type) {
             case SDKErrorType.NotSupported:
                 console.error("WebGLRenderer not supported:", result2.error);
                 break;
             case SDKErrorType.OutOfMemory:
                 console.error("WebGLRenderer out of memory:", result2.error);
                 break;
             default:
                 console.error("WebGLRenderer error:", result2.error);
         }
    });

    webglRenderer.events.onDestroyed.subscribe((renderer, _) => {
         console.log("WebGLRenderer destroyed.");
    });
}

````

```ts
import { Scene } from "@xeokit/sdk/scene";
import { Data } from "@xeokit/sdk/data";
import { WebGLRenderer } from "@xeokit/sdk/webglrenderer";
import { Viewer } from "@xeokit/sdk/viewer";
import { CameraControl } from "@xeokit/sdk/cameracontrol";
import { XGFLoader, XGFExporter } from "@xeokit/sdk/xgf";

const scene = new Scene();
const data = new Data();

const viewer = new Viewer({
    scene
});

const renderer = new WebGLRenderer({
  viewer
});

const viewResult = viewer.createView({
    id: "myView",
    elementId: "myCanvas"
});

const view = viewResult.view;

view.camera.eye = [1841982.93, 10.03, -5173286.74];
view.camera.look = [1842009.49, 9.68, -5173295.85];
view.camera.up = [0.0, 1.0, 0.0];

new CameraControl(view, {});

const sceneModelResult = scene.createModel({ id: "myModel" });
const sceneModel = sceneModelResult.model;

const dataModelResult = data.createModel({ id: "myModel" });
const dataModel = dataModelResult.model;

const xgfLoader = new XGFLoader();

fetch("model.bim")
    .then(response => response.json())
    .then(fileData => {
        xgfLoader.load({ fileData, sceneModel, dataModel })
            .then(() => {
                // Loaded
            })
            .catch(err => {
                sceneModel.destroy();
                dataModel.destroy();
                console.error(`Error loading XGF: ${err}`);
            });
    })
    .catch(err => {
        console.error(`Error fetching XGF file: ${err}`);
    });
```

